/* The fixed drawings of the bench screens (scr_art.c, generated by tools/make_scr_art.py from the
 * approved mockups' geometry). Pure C. */
#ifndef SCR_ART_H
#define SCR_ART_H

#include <stdint.h>

/* A drawing at a fixed place on the screen: h rows from (x, y) down, bit 63 of a row at column x. */
typedef struct {
  int8_t x, y;
  uint8_t h;
  const uint64_t *rows;
} scr_art;

extern const scr_art scr_art_face;   /* HACK THE PLANET: ring, patch, strap, smile (no eye) */
extern const scr_art scr_art_rose;   /* the vane compass: a dot every 4 degrees, a tick every 45 */

#endif
